\section{Análisis de caso}

\subsection{<Criterio/Caso: título del caso>}

\textbf{Texto normativo de partida.} <Artículo/norma que enmarca la controversia y qué expresión se debe interpretar> \citep{<fuente>}.

\textbf{Hechos.} <Hechos relevantes: qué ocurrió, decisión inicial y su revisión> \citep{<fuente>}.

\textbf{Normas jurídicas aplicadas.} <Norma directa + normas de armonización (constitucional, leyes generales)> \citep{<fuentes>}.

\textbf{Problema jurídico.} <La pregunta jurídica precisa; el punto crítico de la interpretación>.

\textbf{Interpretación literal.} <Lectura gramatical de la norma>.
\textbf{Interpretación histórica.} <Antecedentes y concepción tradicional>.
\textbf{Interpretación teleológica.} <Fin de la norma y bien jurídico protegido>.
\textbf{Interpretación sistemática.} <Coherencia con el sistema de derechos>.

\textbf{Postura y consecuencia.} <Lectura propia: por qué el criterio es correcto/incorrecto, qué corrige, qué límite deja>.

\textbf{Argumentos a favor.}
\begin{enumerate}
  \item \textbf{<Título del argumento>.} <Desarrollo>.
\end{enumerate}

\textbf{Argumentos en contra.}
\begin{enumerate}
  \item \textbf{<Título de la objeción>.} <Desarrollo>.
\end{enumerate}
